// kumiko.hello-c: a WASM plugin in C, the reference plugin not written in Rust (spec,
// section 16; MVP criterion 16). It speaks KPP through the `kumiko:plugin` WIT world only:
// `handle` receives host-to-plugin requests, `kumiko_plugin_host_call` sends requests back.
//
// Memory follows the canonical ABI as generated by wit-bindgen: strings passed to an export
// belong to it and are freed here; strings it returns are freed by the generated post-return
// code, so they are heap copies; results of host calls belong to the caller.

#include <stdio.h>
#include <string.h>

#include "kumiko_plugin.h"

// KPP error codes (sdk/schema/kpp.schema.json).
#define KPP_METHOD_NOT_FOUND (-32601)
#define KPP_NOT_FOUND (-32804)

typedef kumiko_plugin_string_t string_t;
typedef exports_kumiko_plugin_plugin_rpc_error_t rpc_error_t;

static int greetings = 0;

static bool equals(const string_t *s, const char *text) {
    size_t n = strlen(text);
    return s->len == n && memcmp(s->ptr, text, n) == 0;
}

// Whether the params of `command/invoke` name `command`. The host sends compact JSON; a real
// plugin would use a JSON parser.
static bool invokes(const string_t *params, const char *command) {
    char needle[128];
    int n = snprintf(needle, sizeof needle, "\"command\":\"%s\"", command);
    if (n <= 0 || (size_t)n >= sizeof needle) {
        return false;
    }
    for (size_t i = 0; i + (size_t)n <= params->len; i++) {
        if (memcmp(params->ptr + i, needle, (size_t)n) == 0) {
            return true;
        }
    }
    return false;
}

static bool reply(string_t *ret, const char *json) {
    kumiko_plugin_string_dup(ret, json);
    return true;
}

static bool fail(rpc_error_t *err, int32_t code, const char *message, size_t len) {
    err->code = code;
    kumiko_plugin_string_dup_n(&err->message, message, len);
    err->data.is_some = false;
    return false;
}

static bool fail_text(rpc_error_t *err, int32_t code, const char *message) {
    return fail(err, code, message, strlen(message));
}

static bool greet(string_t *ret) {
    char json[96];
    greetings++;
    snprintf(json, sizeof json, "{\"greeting\":\"Hello from C\",\"count\":%d}", greetings);
    return reply(ret, json);
}

// Sets `hello-c.greeted` through the host; keys outside `hello-c.*` would be refused.
static bool remember(string_t *ret, rpc_error_t *err) {
    string_t method, params, answer;
    kumiko_plugin_host_rpc_error_t host_error;
    kumiko_plugin_string_set(&method, "command/setContext");
    kumiko_plugin_string_set(&params, "{\"key\":\"hello-c.greeted\",\"value\":true}");
    if (!kumiko_plugin_host_call(&method, &params, &answer, &host_error)) {
        bool result = fail(err, host_error.code, (const char *)host_error.message.ptr,
                           host_error.message.len);
        kumiko_plugin_host_rpc_error_free(&host_error);
        return result;
    }
    kumiko_plugin_string_free(&answer);
    return reply(ret, "true");
}

bool exports_kumiko_plugin_plugin_handle(string_t *method, string_t *params, string_t *ret,
                                         rpc_error_t *err) {
    bool result;
    if (equals(method, "initialize")) {
        result = reply(ret, "{\"apiVersion\":\"0.1.0\",\"pluginCapabilities\":{\"methods\":[]}}");
    } else if (equals(method, "shutdown")) {
        result = reply(ret, "null");
    } else if (equals(method, "command/invoke") && invokes(params, "hello-c.greet")) {
        result = greet(ret);
    } else if (equals(method, "command/invoke") && invokes(params, "hello-c.remember")) {
        result = remember(ret, err);
    } else if (equals(method, "command/invoke")) {
        result = fail_text(err, KPP_NOT_FOUND, "unknown command");
    } else {
        result = fail_text(err, KPP_METHOD_NOT_FOUND, "unknown method");
    }
    kumiko_plugin_string_free(method);
    kumiko_plugin_string_free(params);
    return result;
}

void exports_kumiko_plugin_plugin_on_notify(string_t *method, string_t *params) {
    kumiko_plugin_string_free(method);
    kumiko_plugin_string_free(params);
}

void exports_kumiko_plugin_plugin_on_stream(uint32_t id, kumiko_plugin_list_u8_t *data) {
    (void)id;
    kumiko_plugin_list_u8_free(data);
}

void exports_kumiko_plugin_plugin_on_stream_close(uint32_t id) {
    (void)id;
}
